                            string values;
      --jsonargs            consume remaining arguments as positional
                            JSON values;
  -e, --exit-status         set exit status code based on the output;
  -V, --version             show the version;
  --build-configuration     show jq's build configuration;
  -h, --help                show the help;
  --                        terminates argument processing;

Named arguments are also available as $ARGS.named[], while
positional arguments are available as $ARGS.positional[]."""
BUILD_CONFIG = "--disable-docs --with-oniguruma=builtin --enable-static --enable-all-static --prefix=/usr/local"

class JQError(Exception):
    pass
class CompileError(Exception):
    pass

class EmptyType: pass
EMPTY = EmptyType()

def is_truthy(v):
    return not (v is None or v is False)

def type_name(v):
    if v is None: return "null"
    if isinstance(v, bool): return "boolean"
    if isinstance(v, (int,float)) and not isinstance(v, bool): return "number"
    if isinstance(v, str): return "string"
    if isinstance(v, list): return "array"
    if isinstance(v, dict): return "object"
    return type(v).__name__

def jq_compare(a,b):
    order = {type(None):0, bool:1, int:2, float:2, str:3, list:4, dict:5}
    def rank(x):
        if x is None: return 0
        if isinstance(x,bool): return 1
        if isinstance(x,(int,float)) and not isinstance(x,bool): return 2
        if isinstance(x,str): return 3
        if isinstance(x,list): return 4
        if isinstance(x,dict): return 5
        return 6
    ra, rb = rank(a), rank(b)
    if ra != rb: return -1 if ra < rb else 1
    if isinstance(a, dict):
        ak = sorted(a.keys()); bk = sorted(b.keys())
        c = jq_compare(ak, bk)
        if c: return c
        for k in ak:
            c = jq_compare(a[k], b[k])
            if c: return c
        return 0
    if isinstance(a, list):
        for x,y in zip(a,b):
            c = jq_compare(x,y)
            if c: return c
        return (len(a)>len(b)) - (len(a)<len(b))
    return (a>b) - (a<b)

# --- lexer ---
class Token:
    __slots__ = ('typ','val','pos','end')
    def __init__(self, typ, val=None, pos=0, end=0):
        self.typ=typ; self.val=val; self.pos=pos; self.end=end
    def __repr__(self): return f"Token({self.typ!r},{self.val!r})"

PUNCS = {'[':'LBRACK',']':'RBRACK','{':'LBRACE','}':'RBRACE','(':'LPAREN',')':'RPAREN',',':'COMMA',':':'COLON','|':'PIPE',';':'SEMI','+':'PLUS','-':'MINUS','*':'STAR','/':'SLASH','%':'PERCENT','<':'LT','>':'GT','?':'QMARK'}
MULTI = {'==':'EQ','!=':'NE','<=':'LE','>=':'GE','//':'ALT','..':'DOTDOT','|=':'UPDATE','+=':'PLUSEQ','-=':'MINUSEQ','*=':'STAREQ','/=':'SLASHEQ'}

def lex(s):
    toks=[]; i=0; n=len(s)
    while i<n:
        c=s[i]
        if c.isspace(): i+=1; continue
        if c=='#':
            while i<n and s[i]!='\n': i+=1
            continue
        if i+1<n and s[i:i+2] in MULTI:
            toks.append(Token(MULTI[s[i:i+2]], s[i:i+2], i, i+2)); i+=2; continue
        if c=='.':
            toks.append(Token('DOT','.',i,i+1)); i+=1; continue
        if c in PUNCS:
            toks.append(Token(PUNCS[c], c, i, i+1)); i+=1; continue
        if c=='"':
            dec=json.JSONDecoder()
            try:
                val,end=dec.raw_decode(s[i:])
            except Exception as e:
                raise CompileError("Invalid string literal")
            if not isinstance(val,str): raise CompileError("Invalid string literal")
            toks.append(Token('STRING', val, i, i+end)); i+=end; continue
        if c=='$':
            j=i+1
            if j<n and (s[j].isalpha() or s[j]=='_'):
                j+=1
                while j<n and (s[j].isalnum() or s[j]=='_'):
                    j+=1
                toks.append(Token('VAR', s[i+1:j], i, j)); i=j; continue
            raise CompileError("Invalid variable")
        if c.isdigit() or (c=='-' and i+1<n and (s[i+1].isdigit())):
            j=i
            if s[j]=='-': j+=1
            if j<n and s[j]=='0': j+=1
            else:
                while j<n and s[j].isdigit(): j+=1
            if j<n and s[j]=='.':
                j+=1
                while j<n and s[j].isdigit(): j+=1
            if j<n and s[j] in 'eE':
                j+=1
                if j<n and s[j] in '+-': j+=1
                while j<n and s[j].isdigit(): j+=1
            txt=s[i:j]
            try:
                val=float(txt) if any(ch in txt for ch in '.eE') else int(txt)
            except Exception:
                raise CompileError("Invalid numeric literal")
            toks.append(Token('NUMBER', val, i, j)); i=j; continue
        if c.isalpha() or c=='_':
            j=i+1
            while j<n and (s[j].isalnum() or s[j]=='_'):
                j+=1
            word=s[i:j]
            toks.append(Token('IDENT', word, i, j)); i=j; continue
        raise CompileError(f"Unexpected character {c!r}")
    toks.append(Token('EOF', None, n, n))
    return toks

# --- AST nodes ---
class Node:
    def eval(self, inp, env): raise NotImplementedError
    def paths(self, inp, env):
        # path expressions used by del/getpath-ish: best-effort
        return []

class Identity(Node):
    def eval(self, inp, env): return [inp]
class Literal(Node):
    def __init__(self,v): self.v=v
    def eval(self, inp, env): return [self.v]
class Var(Node):
    def __init__(self,name): self.name=name
    def eval(self, inp, env): return [env.get(self.name, None)]
class Empty(Node):
    def eval(self, inp, env): return []
class Recurse(Node):
    def eval(self, inp, env):
        out=[]
        def rec(v):
            out.append(v)
            if isinstance(v, list):
                for x in v: rec(x)
            elif isinstance(v, dict):
                for x in v.values(): rec(x)
        rec(inp); return out

class Comma(Node):
    def __init__(self,a,b): self.a=a; self.b=b
    def eval(self, inp, env): return self.a.eval(inp, env)+self.b.eval(inp, env)
class Pipe(Node):
    def __init__(self,a,b): self.a=a; self.b=b
    def eval(self, inp, env):
        out=[]
        for v in self.a.eval(inp, env):
            out.extend(self.b.eval(v, env))
        return out
class As(Node):
    def __init__(self,lhs,var,rhs): self.lhs=lhs; self.var=var; self.rhs=rhs
    def eval(self, inp, env):
        out=[]
        for v in self.lhs.eval(inp, env):
            ne=env.copy(); ne[self.var]=v
            out.extend(self.rhs.eval(inp, ne))
        return out
class If(Node):
    def __init__(self,c,t,e): self.c=c; self.t=t; self.e=e
    def eval(self, inp, env):
        conds=self.c.eval(inp, env)
        out=[]
        if not conds:
            return self.e.eval(inp, env)
        for c in conds:
            out.extend((self.t if is_truthy(c) else self.e).eval(inp, env))
        return out

class Field(Node):
    def __init__(self,base,key,opt=False): self.base=base; self.key=key; self.opt=opt
    def eval(self, inp, env):
        out=[]
        for v in self.base.eval(inp, env):
            try:
                if isinstance(v, dict): out.append(v.get(self.key, None))
                elif v is None: out.append(None)
                else:
                    if self.opt: continue
                    raise JQError(f"Cannot index {type_name(v)} with string \"{self.key}\"")
            except JQError:
                if not self.opt: raise
        return out
    def paths(self, inp, env): return [[self.key]]
class Index(Node):
    def __init__(self,base,idx,opt=False): self.base=base; self.idx=idx; self.opt=opt
    def eval(self, inp, env):
        out=[]
        for v in self.base.eval(inp, env):
            idxs=self.idx.eval(v, env)
            for idx in idxs:
                try: out.append(jq_index(v, idx))
                except JQError:
                    if not self.opt: raise
        return out
class Slice(Node):
    def __init__(self,base,a,b,opt=False): self.base=base; self.a=a; self.b=b; self.opt=opt
    def eval(self, inp, env):
        out=[]
        for v in self.base.eval(inp, env):
            av = self.a.eval(v, env)[0] if self.a else None
            bv = self.b.eval(v, env)[0] if self.b else None
            try:
                if isinstance(v, (list,str)):
                    out.append(v[slice(to_int_or_none(av), to_int_or_none(bv))])
                elif v is None: out.append(None)
                else: raise JQError(f"Cannot index {type_name(v)} with object")
            except JQError:
                if not self.opt: raise
        return out
class Iter(Node):
    def __init__(self,base,opt=False): self.base=base; self.opt=opt
    def eval(self, inp, env):
        out=[]
        for v in self.base.eval(inp, env):
            if isinstance(v, list): out.extend(v)
            elif isinstance(v, dict): out.extend(v.values())
            elif v is None:
                if not self.opt: raise JQError("Cannot iterate over null (null)")
            else:
                if not self.opt: raise JQError(f"Cannot iterate over {type_name(v)} ({json_dumps_compact(v)})")
        return out

def to_int_or_none(x):
    if x is None: return None
    return int(x)

def jq_index(v, idx):
    if isinstance(v, list):
        if not isinstance(idx,(int,float)) or isinstance(idx,bool): raise JQError(f"Cannot index array with string \"{idx}\"")
        i=int(idx)
        if i<0: i=len(v)+i
        return v[i] if 0<=i<len(v) else None
    if isinstance(v, dict):
        if not isinstance(idx,str): raise JQError(f"Cannot index object with {type_name(idx)}")
        return v.get(idx, None)
    if isinstance(v,str):
        if isinstance(idx,(int,float)) and not isinstance(idx,bool):
            i=int(idx); i = len(v)+i if i<0 else i
            return v[i] if 0<=i<len(v) else None
        raise JQError(f"Cannot index string with {type_name(idx)}")
    if v is None: return None
    if isinstance(idx,str): raise JQError(f"Cannot index {type_name(v)} with string \"{idx}\"")
    raise JQError(f"Cannot index {type_name(v)} with {type_name(idx)}")

class ArrayCons(Node):
    def __init__(self,expr): self.expr=expr
    def eval(self, inp, env): return [self.expr.eval(inp, env)]
class ObjectCons(Node):
    def __init__(self,pairs): self.pairs=pairs  # list of (keynode/keystr, valnode, dynamic)
    def eval(self, inp, env):
        objects=[{}]
        for key, valnode, dyn in self.pairs:
            keyvals = key.eval(inp, env) if dyn else [key]
            new=[]
            for kv in keyvals:
                if kv is None: continue
                if not isinstance(kv, str): kv = str(kv)
                vals = valnode.eval(inp, env)
                for obj in objects:
                    for vv in vals:
                        no=dict(obj); no[kv]=vv; new.append(no)
            objects=new
        return objects

class Unary(Node):
    def __init__(self,op,a): self.op=op; self.a=a
    def eval(self, inp, env):
        out=[]
        for v in self.a.eval(inp, env):
            if self.op=='-':
                if isinstance(v,(int,float)) and not isinstance(v,bool): out.append(-v)
                else: raise JQError(f"{type_name(v)} cannot be negated")
            elif self.op=='not': out.append(not is_truthy(v))
        return out
class Binary(Node):
    def __init__(self,op,a,b): self.op=op; self.a=a; self.b=b
    def eval(self, inp, env):
        if self.op=='//':
            left=self.a.eval(inp, env)
            good=[v for v in left if v is not None and v is not False]
            return good if good else self.b.eval(inp, env)
        if self.op=='and':
            out=[]
            for x in self.a.eval(inp, env):
                if not is_truthy(x): out.append(False)
                else:
                    for y in self.b.eval(inp, env): out.append(bool(is_truthy(y)))
            return out
        if self.op=='or':
            out=[]
            for x in self.a.eval(inp, env):
                if is_truthy(x): out.append(True)
                else:
                    for y in self.b.eval(inp, env): out.append(bool(is_truthy(y)))
            return out
        out=[]
        la=self.a.eval(inp, env); lb=self.b.eval(inp, env)
        for x in la:
            for y in lb:
                out.append(apply_bin(self.op,x,y))
        return out

def apply_bin(op,x,y):
    if op=='+':
        if x is None: return y
        if y is None: return x
        if isinstance(x,(int,float)) and isinstance(y,(int,float)) and not isinstance(x,bool) and not isinstance(y,bool): return x+y
        if isinstance(x,str) and isinstance(y,str): return x+y
        if isinstance(x,list) and isinstance(y,list): return x+y
        if isinstance(x,dict) and isinstance(y,dict):
            z=dict(x); z.update(y); return z
        raise JQError(f"{type_name(x)} ({json_dumps_compact(x)}) and {type_name(y)} ({json_dumps_compact(y)}) cannot be added")
    if op=='-':
        if isinstance(x,(int,float)) and isinstance(y,(int,float)) and not isinstance(x,bool) and not isinstance(y,bool): return x-y
        if isinstance(x,list) and isinstance(y,list): return [v for v in x if v not in y]
        raise JQError(f"{type_name(x)} and {type_name(y)} cannot be subtracted")
    if op=='*':
        if isinstance(x,(int,float)) and isinstance(y,(int,float)) and not isinstance(x,bool) and not isinstance(y,bool): return x*y
        if isinstance(x,str) and isinstance(y,(int,float)) and not isinstance(y,bool): return x*int(y)
        if isinstance(y,str) and isinstance(x,(int,float)) and not isinstance(x,bool): return y*int(x)
        if isinstance(x,dict) and isinstance(y,dict):
            z=dict(x); z.update(y); return z
        raise JQError(f"{type_name(x)} and {type_name(y)} cannot be multiplied")
    if op=='/':
        if isinstance(x,(int,float)) and isinstance(y,(int,float)) and not isinstance(x,bool) and not isinstance(y,bool): return x/y
        if isinstance(x,str) and isinstance(y,str): return x.split(y)
        raise JQError(f"{type_name(x)} and {type_name(y)} cannot be divided")
    if op=='%':
        if isinstance(x,(int,float)) and isinstance(y,(int,float)) and not isinstance(x,bool) and not isinstance(y,bool): return x%y
        raise JQError(f"{type_name(x)} and {type_name(y)} cannot be divided (remainder)")
    if op=='==': return x==y
    if op=='!=': return x!=y
    c=jq_compare(x,y)
    if op=='<': return c<0
    if op=='>': return c>0
    if op=='<=': return c<=0
    if op=='>=': return c>=0
    raise JQError("unknown operator")

class Builtin(Node):
    def __init__(self,name,args=None): self.name=name; self.args=args or []
    def eval(self, inp, env):
        return eval_builtin(self.name, self.args, inp, env)

class TryCatch(Node):
    def __init__(self,a,b=None): self.a=a; self.b=b
    def eval(self, inp, env):
        try: return self.a.eval(inp, env)
        except JQError as e:
            if self.b: return self.b.eval(str(e), env)
            return []

# --- parser ---
class Parser:
    def __init__(self,toks): self.toks=toks; self.i=0
    def cur(self): return self.toks[self.i]
    def at(self,typ,val=None):
        t=self.cur(); return t.typ==typ and (val is None or t.val==val)
    def eat(self,typ=None,val=None):
        t=self.cur()
        if typ and not self.at(typ,val): raise CompileError(f"Expected {typ}")
        self.i+=1; return t
    def at_ident(self,word): return self.at('IDENT') and self.cur().val==word
    def eat_ident(self,word=None):
        t=self.eat('IDENT')
        if word and t.val!=word: raise CompileError(f"Expected {word}")
        return t
    def parse(self):
        if self.at('EOF'): return Identity()
        n=self.parse_pipe()
        if not self.at('EOF'): raise CompileError("syntax error")
        return n
    def parse_pipe(self):
        left=self.parse_comma()
        if self.at_ident('as'):
            self.eat('IDENT'); var=self.eat('VAR').val; self.eat('PIPE')
            return As(left,var,self.parse_pipe())
        while self.at('PIPE'):
            self.eat('PIPE')
            right=self.parse_comma()
            left=Pipe(left,right)
        return left
    def parse_no_comma_pipe(self):
        left=self.parse_alt()
        if self.at_ident('as'):
            self.eat('IDENT'); var=self.eat('VAR').val; self.eat('PIPE')
            return As(left,var,self.parse_no_comma_pipe())
        while self.at('PIPE'):
            self.eat('PIPE'); left=Pipe(left,self.parse_alt())
        return left
    def parse_comma(self):
        left=self.parse_alt()
        while self.at('COMMA'):
            self.eat('COMMA')
            left=Comma(left,self.parse_alt())
        return left
    def parse_alt(self):
        left=self.parse_or()
        while self.at('ALT'):
            self.eat('ALT'); left=Binary('//',left,self.parse_or())
        return left
    def parse_or(self):
        left=self.parse_and()
        while self.at_ident('or'):
            self.eat('IDENT'); left=Binary('or',left,self.parse_and())
        return left
    def parse_and(self):
        left=self.parse_cmp()
        while self.at_ident('and'):
            self.eat('IDENT'); left=Binary('and',left,self.parse_cmp())
        return left
    def parse_cmp(self):
        left=self.parse_add()
        m={'EQ':'==','NE':'!=','LT':'<','GT':'>','LE':'<=','GE':'>='}
        while self.cur().typ in m:
            op=m[self.eat().typ]; left=Binary(op,left,self.parse_add())
        return left
    def parse_add(self):
        left=self.parse_mul()
        while self.cur().typ in ('PLUS','MINUS'):
            op='+' if self.at('PLUS') else '-'; self.eat(); left=Binary(op,left,self.parse_mul())
        return left
    def parse_mul(self):
        left=self.parse_unary()
        while self.cur().typ in ('STAR','SLASH','PERCENT'):
            op={'STAR':'*','SLASH':'/','PERCENT':'%'}[self.eat().typ]; left=Binary(op,left,self.parse_unary())
        return left
    def parse_unary(self):
        if self.at('MINUS'):
            self.eat('MINUS'); return Unary('-', self.parse_unary())
        if self.at_ident('not'):
            self.eat('IDENT'); return Unary('not', Identity()) if self.is_postfix_boundary() else Unary('not', self.parse_unary())
        return self.parse_postfix()
    def is_postfix_boundary(self):
        return self.cur().typ in ('EOF','COMMA','PIPE','RBRACK','RBRACE','RPAREN','SEMI','COLON')
    def parse_postfix(self):
        node=self.parse_primary()
        while True:
            opt=False
            # .foo, ."foo" after any expression; . alone is handled in primary
            if self.at('DOT'):
                self.eat('DOT')
                if self.at('IDENT'):
                    key=self.eat('IDENT').val
                    if self.at('QMARK'): self.eat('QMARK'); opt=True
                    node=Field(node,key,opt); continue
                if self.at('STRING'):
                    key=self.eat('STRING').val
                    if self.at('QMARK'): self.eat('QMARK'); opt=True
                    node=Field(node,key,opt); continue
                # a bare dot after an expression is a syntax separator in jq only in odd cases
                raise CompileError("syntax error")
            # immediate identifier after leading .: .foo parsed as Identity then IDENT
            if self.at('IDENT') and isinstance(node, Identity):
                word=self.cur().val
                if word not in ('as','then','else','elif','end','and','or'):
                    self.eat('IDENT')
                    if self.at('QMARK'): self.eat('QMARK'); opt=True
                    node=Field(node,word,opt); continue
            if self.at('LBRACK'):
                self.eat('LBRACK')
                if self.at('RBRACK'):
                    self.eat('RBRACK')
                    if self.at('QMARK'): self.eat('QMARK'); opt=True
                    node=Iter(node,opt); continue
                # slice with omitted start
                if self.at('COLON'):
                    self.eat('COLON')
                    end=None if self.at('RBRACK') else self.parse_pipe()
                    self.eat('RBRACK')
                    if self.at('QMARK'): self.eat('QMARK'); opt=True
                    node=Slice(node,None,end,opt); continue
                expr=self.parse_pipe()
                if self.at('COLON'):
                    self.eat('COLON')
                    end=None if self.at('RBRACK') else self.parse_pipe()
                    self.eat('RBRACK')
                    if self.at('QMARK'): self.eat('QMARK'); opt=True
                    node=Slice(node,expr,end,opt); continue
                self.eat('RBRACK')
                if self.at('QMARK'): self.eat('QMARK'); opt=True
                node=Index(node,expr,opt); continue
            if self.at('QMARK'):
                # optional marker for whole expression: silently ignore errors
                self.eat('QMARK'); node=TryCatch(node,None); continue
            break
        return node
    def parse_primary(self):
        if self.at('NUMBER'): return Literal(self.eat('NUMBER').val)
        if self.at('STRING'): return Literal(self.eat('STRING').val)
        if self.at('VAR'): return Var(self.eat('VAR').val)
        if self.at('DOT'):
            self.eat('DOT'); return Identity()
        if self.at('DOTDOT'):
            self.eat('DOTDOT'); return Recurse()
        if self.at('LBRACK'):
            self.eat('LBRACK')
            if self.at('RBRACK'):
                self.eat('RBRACK'); return Literal([])
            expr=self.parse_pipe()
            self.eat('RBRACK')
            return ArrayCons(expr)
        if self.at('LBRACE'):
            return self.parse_object()
        if self.at('LPAREN'):
            self.eat('LPAREN'); n=self.parse_pipe(); self.eat('RPAREN'); return n
        if self.at_ident('true'):
            self.eat('IDENT'); return Literal(True)
        if self.at_ident('false'):
            self.eat('IDENT'); return Literal(False)
        if self.at_ident('null'):
            self.eat('IDENT'); return Literal(None)
        if self.at_ident('empty'):
            self.eat('IDENT'); return Empty()
        if self.at_ident('if'):
            return self.parse_if()
        if self.at_ident('try'):
            self.eat('IDENT'); a=self.parse_pipe(); b=None
            if self.at_ident('catch'):
                self.eat('IDENT'); b=self.parse_pipe()
            return TryCatch(a,b)
        if self.at('IDENT'):
            name=self.eat('IDENT').val
            if self.at('LPAREN'):
                self.eat('LPAREN'); args=[]
                if not self.at('RPAREN'):
                    while True:
                        args.append(self.parse_pipe())
                        if self.at('SEMI') or self.at('COMMA'):
                            self.eat(); continue
                        break
                self.eat('RPAREN')
                return Builtin(name,args)
            return Builtin(name,[])
        raise CompileError("syntax error")
    def parse_if(self):
        self.eat_ident('if')
        cond=self.parse_pipe()
        self.eat_ident('then')
        then=self.parse_pipe()
        if self.at_ident('elif'):
            elsepart=self.parse_if_elif()
        else:
            self.eat_ident('else')
            elsepart=self.parse_pipe()
        self.eat_ident('end')
        return If(cond,then,elsepart)
    def parse_if_elif(self):
        self.eat_ident('elif')
        cond=self.parse_pipe(); self.eat_ident('then'); then=self.parse_pipe()
        if self.at_ident('elif'): elsepart=self.parse_if_elif()
        else:
            self.eat_ident('else'); elsepart=self.parse_pipe()
        return If(cond,then,elsepart)
    def parse_object(self):
        self.eat('LBRACE'); pairs=[]
        if self.at('RBRACE'):
            self.eat('RBRACE'); return ObjectCons([])
        while True:
            dyn=False; key=None; val=None
            if self.at('IDENT'):
                word=self.eat('IDENT').val
                if self.at('COLON'):
                    self.eat('COLON'); key=word; val=self.parse_no_comma_pipe()
                else:
                    key=word; val=Field(Identity(),word)
            elif self.at('STRING'):
                word=self.eat('STRING').val
                if self.at('COLON'):
                    self.eat('COLON'); key=word; val=self.parse_no_comma_pipe()
                else:
                    key=word; val=Field(Identity(),word)
            elif self.at('LPAREN'):
                self.eat('LPAREN'); key=self.parse_pipe(); self.eat('RPAREN'); self.eat('COLON'); dyn=True; val=self.parse_no_comma_pipe()
            else:
                raise CompileError("syntax error in object")
            pairs.append((key,val,dyn))
            if self.at('COMMA'):
                self.eat('COMMA')
                if self.at('RBRACE'): break
                continue
            break
        self.eat('RBRACE'); return ObjectCons(pairs)

# --- builtins ---
def eval_arg(arg, inp, env): return arg.eval(inp, env)
def eval_arg_one(arg, inp, env):
    vals=arg.eval(inp, env); return vals[0] if vals else None

def eval_builtin(name,args,inp,env):
    if name in ('length','utf8bytelength') and not args:
        if name=='utf8bytelength':
            if isinstance(inp,str): return [len(inp.encode())]
            raise JQError(f"{type_name(inp)} has no utf8bytelength")
        if inp is None: return [0]
        if isinstance(inp,(str,list,dict)): return [len(inp)]
        if isinstance(inp,(int,float)) and not isinstance(inp,bool): return [abs(inp)]
        return [0]
    if name=='keys' and not args:
        if isinstance(inp,dict): return [sorted(inp.keys())]
        if isinstance(inp,list): return [list(range(len(inp)))]
        raise JQError(f"{type_name(inp)} has no keys")
    if name=='keys_unsorted' and not args:
        if isinstance(inp,dict): return [list(inp.keys())]
        if isinstance(inp,list): return [list(range(len(inp)))]
        raise JQError(f"{type_name(inp)} has no keys")
    if name=='type' and not args: return [type_name(inp)]
    if name=='values' and not args: return [] if inp is None else [inp]
    if name=='scalars' and not args: return [inp] if not isinstance(inp,(list,dict)) else []
    if name=='arrays' and not args: return [inp] if isinstance(inp,list) else []
    if name=='objects' and not args: return [inp] if isinstance(inp,dict) else []
    if name=='iterables' and not args: return [inp] if isinstance(inp,(list,dict)) else []
    if name=='booleans' and not args: return [inp] if isinstance(inp,bool) else []
    if name=='numbers' and not args: return [inp] if isinstance(inp,(int,float)) and not isinstance(inp,bool) else []
    if name=='strings' and not args: return [inp] if isinstance(inp,str) else []
    if name=='nulls' and not args: return [inp] if inp is None else []
    if name=='not' and not args: return [not is_truthy(inp)]
    if name=='has' and len(args)==1:
        k=eval_arg_one(args[0], inp, env)
        if isinstance(inp,dict):
            if not isinstance(k,str): return [False]
            return [k in inp]
        if isinstance(inp,list):
            if not isinstance(k,(int,float)) or isinstance(k,bool): raise JQError(f"Cannot check whether array has a {type_name(k)} key")
            i=int(k); return [0 <= (i if i>=0 else len(inp)+i) < len(inp)]
        raise JQError(f"Cannot check whether {type_name(inp)} has a key")
    if name=='in' and len(args)==1:
        obj=eval_arg_one(args[0], inp, env)
        if isinstance(obj,dict): return [str(inp) in obj]
        if isinstance(obj,list) and isinstance(inp,(int,float)): return [0<=int(inp)<len(obj)]
        return [False]
    if name=='map' and len(args)==1:
        if isinstance(inp,dict): seq=list(inp.values())
        elif isinstance(inp,list): seq=inp
        else: raise JQError(f"Cannot iterate over {type_name(inp)}")
        arr=[]
        for x in seq: arr.extend(args[0].eval(x, env))
        return [arr]
    if name=='map_values' and len(args)==1:
        if isinstance(inp,list):
            return [[(args[0].eval(x, env) or [None])[0] for x in inp]]
        if isinstance(inp,dict):
            return [{k:(args[0].eval(v, env) or [None])[0] for k,v in inp.items()}]
        raise JQError(f"Cannot iterate over {type_name(inp)}")
    if name=='select' and len(args)==1:
        res=[]
        for v in args[0].eval(inp, env):
            if is_truthy(v): res.append(inp)
        return res
    if name=='add' and not args:
        if inp is None: return [None]
        if not isinstance(inp,list): raise JQError(f"Cannot iterate over {type_name(inp)}")
        if not inp: return [None]
        acc=inp[0]
        for x in inp[1:]: acc=apply_bin('+', acc, x)
        return [acc]
    if name=='range':
        vals=[eval_arg_one(a, inp, env) for a in args]
        if len(vals)==1: start,end,step=0,vals[0],1
        elif len(vals)==2: start,end,step=vals[0],vals[1],1
        elif len(vals)==3: start,end,step=vals
        else: raise CompileError("range arity")
        out=[]; x=int(start); end=int(end); step=int(step)
        if step==0: return []
        if step>0:
            while x<end: out.append(x); x+=step
        else:
            while x>end: out.append(x); x+=step
        return out
    if name=='sort' and not args:
        if not isinstance(inp,list): raise JQError("sort input must be an array")
        return [sorted(inp, key=cmp_to_key(jq_compare))]
    if name=='sort_by' and len(args)==1:
        if not isinstance(inp,list): raise JQError("sort_by input must be an array")
        return [sorted(inp, key=cmp_to_key(lambda a,b: jq_compare((args[0].eval(a, env) or [None])[0], (args[0].eval(b, env) or [None])[0])))]
    if name=='group_by' and len(args)==1:
        arr=eval_builtin('sort_by',args,inp,env)[0]
        groups=[]; last_marker=object(); cur=[]; last=last_marker
        for x in arr:
            k=(args[0].eval(x, env) or [None])[0]
            if last is last_marker or jq_compare(k,last)==0: cur.append(x)
            else: groups.append(cur); cur=[x]
            last=k
        if cur: groups.append(cur)
        return [groups]
    if name in ('min','max') and not args:
        if not isinstance(inp,list) or not inp: return [None]
        return [min(inp, key=cmp_to_key(jq_compare)) if name=='min' else max(inp, key=cmp_to_key(jq_compare))]
    if name in ('min_by','max_by') and len(args)==1:
        if not isinstance(inp,list) or not inp: return [None]
        def keycmp(a,b): return jq_compare((args[0].eval(a, env) or [None])[0], (args[0].eval(b, env) or [None])[0])
        return [min(inp, key=cmp_to_key(keycmp)) if name=='min_by' else max(inp, key=cmp_to_key(keycmp))]
    if name=='unique' and not args:
        if not isinstance(inp,list): raise JQError("unique input must be an array")
        arr=sorted(inp,key=cmp_to_key(jq_compare)); out=[]
        for x in arr:
            if not out or jq_compare(out[-1],x)!=0: out.append(x)
        return [out]
    if name=='unique_by' and len(args)==1:
        arr=eval_builtin('sort_by',args,inp,env)[0]; out=[]; keys=[]
        for x in arr:
            k=(args[0].eval(x,env) or [None])[0]
            if not keys or jq_compare(keys[-1],k)!=0: keys.append(k); out.append(x)
        return [out]
    if name=='reverse' and not args:
        if isinstance(inp,(list,str)): return [inp[::-1]]
        raise JQError(f"{type_name(inp)} cannot be reversed")
    if name=='contains' and len(args)==1:
        needle=eval_arg_one(args[0], inp, env); return [jq_contains(inp, needle)]
    if name=='inside' and len(args)==1:
        hay=eval_arg_one(args[0], inp, env); return [jq_contains(hay, inp)]
    if name in ('startswith','endswith') and len(args)==1:
        s=eval_arg_one(args[0], inp, env)
        if not isinstance(inp,str) or not isinstance(s,str): raise JQError("startswith/endswith requires strings")
        return [inp.startswith(s) if name=='startswith' else inp.endswith(s)]
    if name=='split' and len(args)>=1:
        sep=eval_arg_one(args[0], inp, env)
        if not isinstance(inp,str) or not isinstance(sep,str): raise JQError("split input and separator must be strings")
        return [inp.split(sep)]
    if name=='join' and len(args)==1:
        sep=eval_arg_one(args[0], inp, env)
        if not isinstance(inp,list): raise JQError("join input must be an array")
        return [str_join(sep, inp)]
    if name=='tostring' and not args:
        if isinstance(inp,str): return [inp]
        return [json_dumps_compact(inp)]
    if name=='tojson' and not args: return [json_dumps_compact(inp)]
    if name=='fromjson' and not args:
        if not isinstance(inp,str): raise JQError("fromjson input must be a string")
        try: return [json.loads(inp)]
        except Exception as e: raise JQError(str(e))
    if name=='tonumber' and not args:
        if isinstance(inp,(int,float)) and not isinstance(inp,bool): return [inp]
        if isinstance(inp,str):
            try:
                return [float(inp) if any(ch in inp for ch in '.eE') else int(inp)]
            except Exception: pass
        raise JQError(f"{type_name(inp)} ({json_dumps_compact(inp)}) cannot be parsed as a number")
    if name=='floor' and not args: return [math.floor(inp)]
    if name=='ceil' and not args: return [math.ceil(inp)]
    if name=='round' and not args: return [math.floor(inp+0.5) if inp>=0 else math.ceil(inp-0.5)]
    if name=='abs' and not args: return [abs(inp)]
    if name=='sqrt' and not args: return [math.sqrt(inp)]
    if name=='pow' and len(args)==1: return [math.pow(inp, eval_arg_one(args[0], inp, env))]
    if name=='to_entries' and not args:
        if isinstance(inp,dict): return [[{'key':k,'value':v} for k,v in inp.items()]]
        if isinstance(inp,list): return [[{'key':i,'value':v} for i,v in enumerate(inp)]]
        raise JQError(f"{type_name(inp)} has no entries")
    if name=='from_entries' and not args:
        if not isinstance(inp,list): raise JQError("from_entries requires an array")
        obj={}
        for e in inp:
            if not isinstance(e,dict): raise JQError("from_entries requires object entries")
            k=e.get('key', e.get('Key', e.get('name', e.get('Name'))))
            v=e.get('value', e.get('Value'))
            obj[str(k)] = v
        return [obj]
    if name=='with_entries' and len(args)==1:
        arr=eval_builtin('to_entries',[],inp,env)[0]
        mapped=[]
        for e in arr: mapped.extend(args[0].eval(e,env))
        return eval_builtin('from_entries',[],mapped,env)
    if name=='paths' and len(args)<=1:
        allp=[]
        def walk(v,p):
            if p:
                if not args or any(is_truthy(x) for x in args[0].eval(v, env)): allp.append(p[:])
            if isinstance(v,list):
                for i,x in enumerate(v): walk(x,p+[i])
            elif isinstance(v,dict):
                for k,x in v.items(): walk(x,p+[k])
        walk(inp,[]); return allp
    if name=='getpath' and len(args)==1:
        p=eval_arg_one(args[0],inp,env); return [get_path(inp,p)]
    if name=='setpath' and len(args)==2:
        p=eval_arg_one(args[0],inp,env); v=eval_arg_one(args[1],inp,env); return [set_path(inp,p,v)]
    if name=='del' and len(args)==1:
        # accepts a path expression or array path(s); best-effort
        paths=[]
        val=eval_arg_one(args[0], inp, env)
        if isinstance(val,list) and (not val or all(isinstance(x,(str,int)) for x in val)):
            paths=[val]
        elif isinstance(val,list) and all(isinstance(x,list) for x in val): paths=val
        return [delete_paths(inp, paths)]
    if name=='flatten' and len(args)<=1:
        depth=eval_arg_one(args[0],inp,env) if args else None
        return [flatten(inp, depth)]
    if name=='first':
        if args:
            vals=args[0].eval(inp,env); return vals[:1]
        if isinstance(inp,list): return [inp[0]] if inp else []
        return [inp]
    if name=='last':
        if args:
            vals=args[0].eval(inp,env); return vals[-1:] if vals else []
        if isinstance(inp,list): return [inp[-1]] if inp else []
        return [inp]
    if name=='nth' and len(args)==1:
        n=eval_arg_one(args[0],inp,env)
        if isinstance(inp,list): return [inp[int(n)]] if -len(inp)<=int(n)<len(inp) else []
        return []
    if name=='limit' and len(args)==2:
        n=int(eval_arg_one(args[0],inp,env)); return args[1].eval(inp,env)[:n]
    if name=='error' and len(args)<=1:
        msg=eval_arg_one(args[0],inp,env) if args else inp
        raise JQError(str(msg))
    if name=='halt' and not args:
        raise SystemExit(0)
    if name=='halt_error':
        code=int(eval_arg_one(args[0],inp,env) if args else 5)
        raise SystemExit(code)
    # format filters @json, @csv are lexed poorly as unexpected @, so not here.
    raise CompileError(f"{name}/{'%d'%len(args)} is not defined")

def jq_contains(a,b):
    if isinstance(a,str) and isinstance(b,str): return b in a
    if isinstance(a,list): return all(any(jq_contains(x,y) if isinstance(y,(list,dict)) else x==y for x in a) for y in b) if isinstance(b,list) else False
    if isinstance(a,dict) and isinstance(b,dict): return all(k in a and jq_contains(a[k],v) for k,v in b.items())
    return a==b

def str_join(sep, arr):
    parts=[]
    for x in arr:
        if x is None: parts.append('')
        elif isinstance(x,str): parts.append(x)
        else: parts.append(json_dumps_compact(x) if isinstance(x,(list,dict)) else str(x).lower() if isinstance(x,bool) else str(x))
    return str(sep).join(parts)

def get_path(v,p):
    cur=v
    for k in p:
        cur=jq_index(cur,k)
    return cur

def set_path(v,p,val):
    import copy
    root=copy.deepcopy(v)
    if not p: return val
    cur=root
    for k in p[:-1]: cur=cur[k]
    cur[p[-1]]=val
    return root

def delete_paths(v,paths):
    import copy
    root=copy.deepcopy(v)
    for p in paths:
        if not p: continue
        cur=root
        try:
            for k in p[:-1]: cur=cur[k]
            if isinstance(cur,dict): cur.pop(p[-1],None)
            elif isinstance(cur,list) and isinstance(p[-1],int) and 0<=p[-1]<len(cur): cur.pop(p[-1])
        except Exception: pass
    return root

def flatten(v, depth=None):
    if not isinstance(v,list): return v
    if depth is not None and depth<=0: return v
    out=[]
    for x in v:
        if isinstance(x,list): out.extend(flatten(x, None if depth is None else depth-1))
        else: out.append(x)
    return out

# --- IO and formatting ---
def json_dumps_compact(v, ascii_only=False, sort_keys=False):
    return json.dumps(v, ensure_ascii=ascii_only, sort_keys=sort_keys, separators=(',', ':'), allow_nan=False)

def dumps_pretty(v, opts):
    indent = '\t' if opts.get('tab') else opts.get('indent',2)
    if opts.get('compact'):
        return json.dumps(v, ensure_ascii=opts.get('ascii',False), sort_keys=opts.get('sort',False), separators=(',', ':'), allow_nan=False)
    return json.dumps(v, ensure_ascii=opts.get('ascii',False), sort_keys=opts.get('sort',False), indent=indent, allow_nan=False)

COL_RESET='\033[0m'
def color_json(s):
    # A close approximation of jq's default color scheme: punctuation bold, keys blue, strings green, null grey, booleans yellow.
    out=[]; i=0; n=len(s); expect_key_stack=[]
    while i<n:
        c=s[i]
        if c=='"':
            j=i+1; esc=False
            while j<n:
                if esc: esc=False
                elif s[j]=='\\': esc=True
                elif s[j]=='"': j+=1; break
                j+=1
            # look ahead to decide key
            k=j
            while k<n and s[k] in ' \t': k+=1
            col='\033[1;34m' if k<n and s[k]==':' else '\033[0;32m'
            out.append(col+s[i:j]+COL_RESET); i=j; continue
        if c in '{}[],:': out.append('\033[1;39m'+c+COL_RESET); i+=1; continue
        if s.startswith('null',i): out.append('\033[0;90mnull'+COL_RESET); i+=4; continue
        if s.startswith('true',i): out.append('\033[0;39mtrue'+COL_RESET); i+=4; continue
        if s.startswith('false',i): out.append('\033[0;39mfalse'+COL_RESET); i+=5; continue
        m=re.match(r'-?\d+(?:\.\d+)?(?:[eE][+-]?\d+)?', s[i:])
        if m:
            out.append('\033[0;39m'+m.group(0)+COL_RESET); i+=len(m.group(0)); continue
        out.append(c); i+=1
    return ''.join(out)

def parse_json_stream(text):
    dec=json.JSONDecoder(); i=0; vals=[]; n=len(text)
    while True:
        while i<n and text[i].isspace(): i+=1
        if i>=n: break
        try:
            v,j=dec.raw_decode(text,i)
        except Exception as e:
            raise JQError(f"parse error: Invalid numeric literal at line 1, column {i+1}")
        vals.append(v); i=j
    return vals

def read_inputs(files, opts):
    if opts.get('null_input'): return [None]
    raw=opts.get('raw_input')
    slurp=opts.get('slurp')
    if not files: contents=[sys.stdin.read()]
    else:
        contents=[]
        for f in files:
            with open(f, 'r', encoding='utf-8') as fh: contents.append(fh.read())
    text=''.join(contents)
    if raw:
        if slurp: return [text]
        # splitlines without keeping terminators; final empty line after trailing newline is not an input
        if text=='': return []
        return text.splitlines()
    vals=parse_json_stream(text)
    return [vals] if slurp else vals

def cli_error(msg):
    sys.stderr.write(f"jq: {msg}\nUse jq --help for help with command-line options,\nor see the jq manpage, or online docs at https://jqlang.org\n")
    return 2

def parse_args(argv):
    opts={'indent':2,'named':{},'positional':[]}; filter_arg=None; files=[]; i=0; stop_opts=False
    while i<len(argv):
        a=argv[i]
        if stop_opts:
            if filter_arg is None: filter_arg=a
            else: files.append(a)
            i+=1; continue
        if a=='--': stop_opts=True; i+=1; continue
        if a in ('-V','--version'):
            print(VERSION); raise SystemExit(0)
        if a in ('-h','--help'):
            print(HELP); raise SystemExit(0)
        if a=='--build-configuration':
            print(BUILD_CONFIG); raise SystemExit(0)
        if a in ('-n','--null-input'): opts['null_input']=True; i+=1; continue
        if a in ('-R','--raw-input'): opts['raw_input']=True; i+=1; continue
        if a in ('-s','--slurp'): opts['slurp']=True; i+=1; continue
        if a in ('-c','--compact-output'): opts['compact']=True; i+=1; continue
        if a in ('-r','--raw-output'): opts['raw_output']=True; i+=1; continue
        if a=='--raw-output0': opts['raw_output']=True; opts['raw0']=True; i+=1; continue
        if a in ('-j','--join-output'): opts['raw_output']=True; opts['join']=True; i+=1; continue
        if a in ('-a','--ascii-output'): opts['ascii']=True; i+=1; continue
        if a in ('-S','--sort-keys'): opts['sort']=True; i+=1; continue
        if a in ('-C','--color-output'): opts['color']=True; i+=1; continue
        if a in ('-M','--monochrome-output'): opts['color']=False; i+=1; continue
        if a=='--tab': opts['tab']=True; i+=1; continue
        if a=='--indent':
            if i+1>=len(argv): raise SystemExit(cli_error('--indent takes a number between -1 and 7'))
            try: n=int(argv[i+1])
            except: raise SystemExit(cli_error('--indent takes a number between -1 and 7'))
            if n<-1 or n>7: raise SystemExit(cli_error('--indent takes a number between -1 and 7'))
            opts['indent']=None if n<0 else n; opts['compact']= n<0; i+=2; continue
        if a=='--unbuffered': opts['unbuffered']=True; i+=1; continue
        if a in ('--stream','--stream-errors','--seq'):
            opts[a[2:].replace('-','_')]=True; i+=1; continue
        if a in ('-e','--exit-status'): opts['exit_status']=True; i+=1; continue
        if a in ('-f','--from-file'):
            if i+1>=len(argv): raise SystemExit(cli_error('-f takes a filename'))
            with open(argv[i+1],encoding='utf-8') as fh: filter_arg=fh.read()
            i+=2; continue
        if a in ('-L','--library-path'):
            i+=2; continue
        if a=='--arg':
            if i+2>=len(argv): raise SystemExit(cli_error('--arg takes two parameters (e.g. --arg varname value)'))
            opts['named'][argv[i+1]]=argv[i+2]; i+=3; continue
        if a=='--argjson':
            if i+2>=len(argv): raise SystemExit(cli_error('--argjson takes two parameters (e.g. --argjson varname text)'))
            try: opts['named'][argv[i+1]]=json.loads(argv[i+2])
            except Exception: raise SystemExit(cli_error('invalid JSON text passed to --argjson'))
            i+=3; continue
        if a=='--rawfile':
            if i+2>=len(argv): raise SystemExit(cli_error('--rawfile takes two parameters'))
            with open(argv[i+2],encoding='utf-8') as fh: opts['named'][argv[i+1]]=fh.read()
            i+=3; continue
        if a=='--slurpfile':
            if i+2>=len(argv): raise SystemExit(cli_error('--slurpfile takes two parameters'))
            with open(argv[i+2],encoding='utf-8') as fh: opts['named'][argv[i+1]]=parse_json_stream(fh.read())
            i+=3; continue
        if a=='--args':
            if filter_arg is None:
                if i+1>=len(argv): raise SystemExit(cli_error('missing filter'))
                filter_arg=argv[i+1]; opts['positional']=argv[i+2:]
            else: opts['positional']=argv[i+1:]
            break
        if a=='--jsonargs':
            if filter_arg is None:
                if i+1>=len(argv): raise SystemExit(cli_error('missing filter'))
                filter_arg=argv[i+1]; rest=argv[i+2:]
            else: rest=argv[i+1:]
            try: opts['positional']=[json.loads(x) for x in rest]
            except Exception: raise SystemExit(cli_error('invalid JSON text passed to --jsonargs'))
            break
        # short option clusters like -cSre
        if a.startswith('-') and a!='-':
            ok=True; j=1
            while j<len(a):
                ch=a[j]
                if ch=='n': opts['null_input']=True
                elif ch=='R': opts['raw_input']=True
                elif ch=='s': opts['slurp']=True
                elif ch=='c': opts['compact']=True
                elif ch=='r': opts['raw_output']=True
                elif ch=='j': opts['raw_output']=True; opts['join']=True
                elif ch=='a': opts['ascii']=True
                elif ch=='S': opts['sort']=True
                elif ch=='C': opts['color']=True
                elif ch=='M': opts['color']=False
                elif ch=='e': opts['exit_status']=True
                else: ok=False; break
                j+=1
            if ok: i+=1; continue
            raise SystemExit(cli_error(f"Unknown option {a}"))
        if filter_arg is None: filter_arg=a
        else: files.append(a)
        i+=1
    if filter_arg is None:
        # jq with no arguments exits successfully without output when noninteractive here.
        raise SystemExit(0)
    return opts, filter_arg, files

def output_value(v, opts):
    if opts.get('raw_output') and isinstance(v,str):
        if opts.get('raw0') and '\x00' in v:
            raise JQError('Cannot dump a string containing NUL with --raw-output0 option')
        s=v
    elif opts.get('raw_output'):
        s=json_dumps_compact(v, opts.get('ascii',False), opts.get('sort',False))
    else:
        s=dumps_pretty(v, opts)
        if opts.get('color'): s=color_json(s)
    end=''
    if opts.get('raw0'): end='\0'
    elif opts.get('join'): end=''
    else: end='\n'
    sys.stdout.write(s+end)
    if opts.get('unbuffered'): sys.stdout.flush()

def main(argv):
    try:
        opts, filt, files=parse_args(argv)
        env=dict(opts.get('named',{}))
        env['ARGS']={'positional': opts.get('positional',[]), 'named': opts.get('named',{})}
        ast=Parser(lex(filt)).parse()
        inputs=read_inputs(files, opts)
        last=EMPTY; any_out=False
        for inp in inputs:
            outs=ast.eval(inp, env)
            for v in outs:
                any_out=True; last=v; output_value(v, opts)
        if opts.get('exit_status'):
            if not any_out: return 4
            return 0 if is_truthy(last) else 1
        return 0
    except CompileError as e:
        sys.stderr.write(f"jq: error: {e}\njq: 1 compile error\n")
        return 3
    except JQError as e:
        msg=str(e)
        if msg.startswith('parse error:'):
            sys.stderr.write('jq: '+msg+'\n')
        else:
            sys.stderr.write(f"jq: error (at <unknown>): {msg}\n")
        return 5
    except BrokenPipeError:
        return 0

if __name__=='__main__':
    sys.exit(main(sys.argv[1:]))
