BUILD_CONFIG = "--disable-docs --with-oniguruma=builtin --enable-static --enable-all-static --prefix=/usr/local"

class JQError(Exception):
    pass
class CompileError(Exception):
    pass

class EmptyType: pass
EMPTY = EmptyType()

def is_truthy(v):
    return not (v is None or v is False)

def type_name(v):
    if v is None: return "null"
    if isinstance(v, bool): return "boolean"
    if isinstance(v, (int,float)) and not isinstance(v, bool): return "number"
    if isinstance(v, str): return "string"
    if isinstance(v, list): return "array"
    if isinstance(v, dict): return "object"
    return type(v).__name__

def jq_compare(a,b):
    order = {type(None):0, bool:1, int:2, float:2, str:3, list:4, dict:5}
    def rank(x):
        if x is None: return 0
        if isinstance(x,bool): return 1
        if isinstance(x,(int,float)) and not isinstance(x,bool): return 2
        if isinstance(x,str): return 3
        if isinstance(x,list): return 4
        if isinstance(x,dict): return 5
        return 6
    ra, rb = rank(a), rank(b)
    if ra != rb: return -1 if ra < rb else 1
    if isinstance(a, dict):
        ak = sorted(a.keys()); bk = sorted(b.keys())
        c = jq_compare(ak, bk)
        if c: return c
        for k in ak:
            c = jq_compare(a[k], b[k])
            if c: return c
        return 0
    if isinstance(a, list):
        for x,y in zip(a,b):
            c = jq_compare(x,y)
            if c: return c
        return (len(a)>len(b)) - (len(a)<len(b))
    return (a>b) - (a<b)

# --- lexer ---
class Token:
    __slots__ = ('typ','val','pos','end')
    def __init__(self, typ, val=None, pos=0, end=0):
        self.typ=typ; self.val=val; self.pos=pos; self.end=end
    def __repr__(self): return f"Token({self.typ!r},{self.val!r})"

PUNCS = {'[':'LBRACK',']':'RBRACK','{':'LBRACE','}':'RBRACE','(':'LPAREN',')':'RPAREN',',':'COMMA',':':'COLON','|':'PIPE',';':'SEMI','+':'PLUS','-':'MINUS','*':'STAR','/':'SLASH','%':'PERCENT','<':'LT','>':'GT','?':'QMARK'}
MULTI = {'==':'EQ','!=':'NE','<=':'LE','>=':'GE','//':'ALT','..':'DOTDOT','|=':'UPDATE','+=':'PLUSEQ','-=':'MINUSEQ','*=':'STAREQ','/=':'SLASHEQ'}

def lex(s):
    toks=[]; i=0; n=len(s)
    while i<n:
        c=s[i]
        if c.isspace(): i+=1; continue
        if c=='#':
            while i<n and s[i]!='\n': i+=1
            continue
        if i+1<n and s[i:i+2] in MULTI:
            toks.append(Token(MULTI[s[i:i+2]], s[i:i+2], i, i+2)); i+=2; continue
        if c=='.':
            toks.append(Token('DOT','.',i,i+1)); i+=1; continue
        if c in PUNCS:
            toks.append(Token(PUNCS[c], c, i, i+1)); i+=1; continue
        if c=='"':
            dec=json.JSONDecoder()
            try:
                val,end=dec.raw_decode(s[i:])
            except Exception as e:
                raise CompileError("Invalid string literal")
            if not isinstance(val,str): raise CompileError("Invalid string literal")
            toks.append(Token('STRING', val, i, i+end)); i+=end; continue
        if c=='$':
            j=i+1
            if j<n and (s[j].isalpha() or s[j]=='_'):
                j+=1
                while j<n and (s[j].isalnum() or s[j]=='_'):
                    j+=1
                toks.append(Token('VAR', s[i+1:j], i, j)); i=j; continue
            raise CompileError("Invalid variable")
        if c.isdigit() or (c=='-' and i+1<n and (s[i+1].isdigit())):
            j=i
            if s[j]=='-': j+=1
            if j<n and s[j]=='0': j+=1
            else:
                while j<n and s[j].isdigit(): j+=1
            if j<n and s[j]=='.':
                j+=1
                while j<n and s[j].isdigit(): j+=1
            if j<n and s[j] in 'eE':
                j+=1
                if j<n and s[j] in '+-': j+=1
                while j<n and s[j].isdigit(): j+=1
            txt=s[i:j]
            try:
                val=float(txt) if any(ch in txt for ch in '.eE') else int(txt)
            except Exception:
                raise CompileError("Invalid numeric literal")
            toks.append(Token('NUMBER', val, i, j)); i=j; continue
        if c.isalpha() or c=='_':
            j=i+1
            while j<n and (s[j].isalnum() or s[j]=='_'):
                j+=1
            word=s[i:j]
            toks.append(Token('IDENT', word, i, j)); i=j; continue
        raise CompileError(f"Unexpected character {c!r}")
    toks.append(Token('EOF', None, n, n))
    return toks

# --- AST nodes ---
class Node:
    def eval(self, inp, env): raise NotImplementedError
    def paths(self, inp, env):
        # path expressions used by del/getpath-ish: best-effort
        return []

class Identity(Node):
    def eval(self, inp, env): return [inp]
class Literal(Node):
    def __init__(self,v): self.v=v
    def eval(self, inp, env): return [self.v]
class Var(Node):
    def __init__(self,name): self.name=name
    def eval(self, inp, env): return [env.get(self.name, None)]
class Empty(Node):
    def eval(self, inp, env): return []
class Recurse(Node):
    def eval(self, inp, env):
        out=[]
        def rec(v):
            out.append(v)
            if isinstance(v, list):
                for x in v: rec(x)
            elif isinstance(v, dict):
                for x in v.values(): rec(x)
        rec(inp); return out

class Comma(Node):
    def __init__(self,a,b): self.a=a; self.b=b
    def eval(self, inp, env): return self.a.eval(inp, env)+self.b.eval(inp, env)
class Pipe(Node):
    def __init__(self,a,b): self.a=a; self.b=b
    def eval(self, inp, env):
        out=[]
        for v in self.a.eval(inp, env):
            out.extend(self.b.eval(v, env))
        return out
class As(Node):
    def __init__(self,lhs,var,rhs): self.lhs=lhs; self.var=var; self.rhs=rhs
    def eval(self, inp, env):
        out=[]
        for v in self.lhs.eval(inp, env):
            ne=env.copy(); ne[self.var]=v
            out.extend(self.rhs.eval(inp, ne))
        return out
class If(Node):
    def __init__(self,c,t,e): self.c=c; self.t=t; self.e=e
    def eval(self, inp, env):
        conds=self.c.eval(inp, env)
        out=[]
        if not conds:
            return self.e.eval(inp, env)
        for c in conds:
            out.extend((self.t if is_truthy(c) else self.e).eval(inp, env))
        return out

class Field(Node):
    def __init__(self,base,key,opt=False): self.base=base; self.key=key; self.opt=opt
    def eval(self, inp, env):
        out=[]
        for v in self.base.eval(inp, env):
            try:
                if isinstance(v, dict): out.append(v.get(self.key, None))
                elif v is None: out.append(None)
                else:
                    if self.opt: continue
                    raise JQError(f"Cannot index {type_name(v)} with string \"{self.key}\"")
            except JQError:
                if not self.opt: raise
